def verify(witness):
    core_gaps = witness['core_gaps']
    if not isinstance(core_gaps, list) or len(core_gaps) != 18:
        raise ValueError('core_gaps must be a list of length 18')
    counts = {1: 0, 2: 0, 3: 0}
    for g in core_gaps:
        if not (isinstance(g, int) and g in (1, 2, 3)):
            raise ValueError('gap outside finite core d in {1,2,3}')
        counts[g] += 1
    if counts != {1: 10, 2: 5, 3: 3}:
        raise ValueError('counts differ from standing lemma values {1:10,2:5,3:3}')
    total = counts[1] + counts[2] + counts[3]
    if total != 18:
        raise ValueError('conservation total mismatch')
    weighted = counts[1]*1 + counts[2]*2 + counts[3]*3
    if weighted != 29:
        raise ValueError('weighted sum mismatch')
    if weighted != 30 - 1:
        raise ValueError('conservation identity violated')
    if witness['conservation_total'] != 18 or witness['weighted_sum'] != 29 or witness['expected_weighted_sum'] != 29 or witness['expected_total'] != 30:
        raise ValueError('declared witness fields inconsistent')
    return True
